use serde_json::{Value, Map};
use std::collections::BTreeMap;

pub fn solve(input: Value) -> Value {
    let mut map = BTreeMap::new();
    if let Value::Array(arr) = input {
        for item in arr {
            if let Value::Array(row) = item {
                if let (Some(key), Some(value)) = (row.get(0), row.get(1)) {
                    if let (Value::Number(k), Value::Number(v)) = (key, value) {
                        map.insert(k.as_i64().unwrap(), v.as_i64().unwrap());
                    }
                }
            }
        }
    }
    let mut result = Vec::new();
    for (key, value) in map {
        result.push(Value::Array(vec![Value::Number(key.into()), Value::Number(value.into())]));
    }
    Value::Array(result)
}
